        # If no meetings, employee is available for all days
        if not meetings:
            return days

        # Sort meetings by start day
        meetings.sort()

        # Merge overlapping meetings
        merged_meetings = []

        for start, end in meetings:
            # If merged_meetings is empty or current meeting doesn't overlap with last one
            if not merged_meetings or merged_meetings[-1][1] < start:
                merged_meetings.append([start, end])
            else:
                # Merge with the last meeting (extend end day)
                merged_meetings[-1][1] = max(merged_meetings[-1][1], end)

        # Calculate total days covered by meetings
        total_meeting_days = 0
        for start, end in merged_meetings:
            total_meeting_days += end - start + 1

        # Return available days (total days minus meeting days)
        return days - total_meeting_days

