def solve():
    # Read input
    grid = []
    for _ in range(3):
        row = list(map(int, input().split()))
        grid.append(row)

    # Define winning positions (3 in a row)
    winning_positions = [
        # Rows
        [0, 1, 2], [3, 4, 5], [6, 7, 8],
        # Columns
        [0, 3, 6], [1, 4, 7], [2, 5, 8],
        # Diagonals
        [0, 4, 8], [2, 4, 6]
    ]

    def is_winner(board, player):
        """Check if player has won"""
        for pos in winning_positions:
            if all(board[i] == player for i in pos):
                return True
        return False

    def is_board_full(board):
        """Check if board is full"""
        return all(cell != 0 for cell in board)

    def get_score(board):
        """Calculate scores for both players"""
        takahashi_score = 0
        aoki_score = 0
        for i, cell in enumerate(board):
            if cell == 1:  # Takahashi (red)
                takahashi_score += grid[i//3][i%3]
            elif cell == 2:  # Aoki (blue)
                aoki_score += grid[i//3][i%3]
        return takahashi_score, aoki_score

    def minimax(board, is_takahashi_turn):
        """Minimax algorithm with memoization"""
        # Check if game has already ended
        if is_winner(board, 1):  # Takahashi won
            return 1, 0  # Takahashi wins
        if is_winner(board, 2):  # Aoki won
            return 0, 1  # Aoki wins

        # Check if board is full
        if is_board_full(board):
            takahashi_score, aoki_score = get_score(board)
            if takahashi_score > aoki_score:
                return 1, 0
            elif takahashi_score < aoki_score:
                return 0, 1
            else:
                return 0, 0  # Tie (but sum is odd, so this won't happen)

        # If it's Takahashi's turn (maximizing player)
        if is_takahashi_turn:
            best_val = -float('inf')

            for i in range(9):
                if board[i] == 0:  # Cell is white
                    board[i] = 1  # Takahashi plays
                    val, _ = minimax(board, False)
                    board[i] = 0  # Undo move

                    if val > best_val:
                        best_val = val

            return best_val, 0

        # If it's Aoki's turn (minimizing player)
        else:
            best_val = float('inf')

            for i in range(9):
                if board[i] == 0:  # Cell is white
                    board[i] = 2  # Aoki plays
                    val, _ = minimax(board, True)
                    board[i] = 0  # Undo move

                    if val < best_val:
                        best_val = val

            return best_val, 0

    # Initialize board with 0 (white), 1 (Takahashi), 2 (Aoki)
    board = [0] * 9

    # Run minimax to determine winner
    winner, _ = minimax(board, True)

    if winner == 1:
        print("Takahashi")
    else:
        print("Aoki")

